using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PersonalLifeTests
{
    static readonly EntityId Kofu=new("site:kofu"),Worker=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    internal static WorldSession Start(bool employee=false,string? policy=null)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],employee?Worker.Value:"person:shingen",42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,voyageRules:VoyageExpense.Standard,economyPolicy:policy??PersonalLife.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static CommandResult Act(WorldSession s,LifeAction a,EntityId? original=null,LifeGoal goal=LifeGoal.WorkPay,long target=0,string? id=null)=>s.ManageLife(new(new(id??"request:life/"+s.Revision),a,Kofu,original,goal,target),s.PlayerControl,s.Revision);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static EntityId Salary(WorldSession s){EntityId other=s.PlayerControl==Worker?new("person:shingen"):Worker;var q=new EntityId("request:life-salary");Good(s.ManageSalary(new(q,SalaryAction.Propose,other,Kofu,Amount:20),s.PlayerControl,s.Revision));Good(s.ManageSalary(new(new("request:life-confirm"),SalaryAction.Confirm,other,Kofu,q),s.PlayerControl,s.Revision));Advance(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[0]);var p=new EntityId("request:life-prepare");Good(s.ManageSalary(new(p,SalaryAction.Prepare,other,Kofu,q,20),s.PlayerControl,s.Revision));Good(s.ManageSalary(new(new("request:life-receive"),SalaryAction.Receive,other,Kofu,q,Preparation:p),s.PlayerControl,s.Revision));return q;}
    static EntityId Food(WorldSession s,long n=1){var id=new EntityId("request:life-food/"+s.Revision);Good(s.TradeRice(new(id,TradeAction.Quote,Kofu,Destination:Kofu,Amount:n),s.PlayerControl,s.Revision));foreach(var a in new[]{TradeAction.Accept,TradeAction.Collect})Good(s.TradeRice(new(new("request:life-trade/"+s.Revision),a,Kofu,id),s.PlayerControl,s.Revision));return id;}
    [Theory][InlineData(false)][InlineData(true)]public void RolesKeepPrivatePurseSeparateFromHouseAndArmy(bool employee){var s=Start(employee);var v=s.PersonalLifeView()!;Assert.Equal(employee?"家臣・随行":"大名",v.Role);Assert.Equal(1000,v.PrivateMoney);Assert.Equal(0,v.PrivateRice);Assert.False(v.HoldsArmy);Assert.Equal(0,v.StipendPayable);Assert.DoesNotContain("HouseRice",System.Text.Encoding.UTF8.GetString(ContractJson.Write(v)));}
    [Fact]public void CreatedRoninUsesSameLifeRulesWithoutGainingHouseAuthority(){var setup=NewGameWorldTests.Setup();var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:test",inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:PersonalLife.Policy));var v=s.PersonalLifeView()!;Assert.Equal("浪人",v.Role);Assert.Null(v.House);var site=v.Site!.Value;Good(s.ManageLife(new(new("request:ronin-rest"),LifeAction.RestOutside,site),s.PlayerControl,s.Revision));Assert.Null(s.CommunityEconomyView());}
    [Theory][InlineData(false)][InlineData(true)]public void RestDoesNotJumpClockOrTransferAnyHouseRice(bool inn){var s=Start();var before=s.DiagnosticSnapshot();Good(Act(s,inn?LifeAction.RestInn:LifeAction.RestOutside));Assert.Equal(0,s.Seconds);Assert.Equal(inn?990:1000,s.PersonalLifeView()!.PrivateMoney);Assert.Equal(inn?7200:14400,s.PersonalLifeView()!.RestUntil);Assert.Equal(before.Communities!.Accounts,s.DiagnosticSnapshot().Communities!.Accounts);}
    [Fact]public void RestBlocksMoveAndInspectUntilExactEnd(){var s=Start();Good(Act(s,LifeAction.RestInn));Assert.Equal(ResultCode.InvalidInput,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:rest-move","castle"),s.Revision).Code);Assert.Equal(ResultCode.InvalidInput,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:rest-inspect"),s.Revision).Code);Advance(s,7199);Assert.NotNull(s.PersonalLifeView()!.ActiveRest);Advance(s,7200);Assert.Null(s.PersonalLifeView()!.ActiveRest);Assert.Equal(7200,s.PersonalLifeView()!.RestSeconds);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:after-rest","castle"),s.Revision));}
    [Fact]public void PartialCancellationKeepsFeeAndElapsedTime(){var s=Start();Good(Act(s,LifeAction.RestInn));var id=s.PersonalLifeView()!.ActiveRest;Advance(s,123);Good(Act(s,LifeAction.CancelRest,id));Assert.Equal(123,s.Seconds);Assert.Equal(123,s.PersonalLifeView()!.RestSeconds);Assert.Equal(990,s.PersonalLifeView()!.PrivateMoney);Assert.Null(s.PersonalLifeView()!.ActiveRest);Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.CancelRest,id).Code);}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(5001)]public void InvalidGoalAmountsAreAtomic(long n){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.SetGoal,target:n).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RetryCannotChargeTwiceOrChangePayload(){var s=Start();var i=new LifeInput(new("request:life-once"),LifeAction.RestInn,Kofu);Good(s.ManageLife(i,s.PlayerControl,s.Revision));var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.ManageLife(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageLife(i with{Action=LifeAction.RestOutside},s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void OtherActorStaleRevisionAndRemoteSiteCannotRest(){var s=Start();var i=new LifeInput(new("request:life-wrong"),LifeAction.RestInn,Kofu);Assert.Equal(ResultCode.NotAvailable,s.ManageLife(i,Worker,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.ManageLife(i,s.PlayerControl,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageLife(i with{Site=new("site:castle")},s.PlayerControl,s.Revision).Code);}
    [Fact]public void LifeIdsCannotBeReusedForTrade(){var s=Start();Good(Act(s,LifeAction.SetGoal,target:20,id:"request:life-shared"));Assert.Equal(ResultCode.IdPayloadConflict,s.TradeRice(new(new("request:life-shared"),TradeAction.Quote,Kofu,Destination:Kofu,Amount:1),s.PlayerControl,s.Revision).Code);}
    [Fact]public void TradeIdsCannotBeReusedForLife(){var s=Start();var id=Food(s);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,LifeAction.SetGoal,target:20,id:id.Value).Code);}
    [Fact]public void SalaryMealConsumesOnlyPrivateRiceAndCannotBeSoldAgain(){var s=Start(true);Salary(s);var house=s.DiagnosticSnapshot().Communities!.Accounts;Good(Act(s,LifeAction.EatPrivateRice));Assert.Equal(19,s.PersonalLifeView()!.PrivateRice);Assert.Equal(1,s.PersonalLifeView()!.MealRiceConsumed);Assert.Equal(house,s.DiagnosticSnapshot().Communities!.Accounts);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:eaten-sell"),TradeAction.OfferOwnRice,Kofu,Destination:Kofu,Amount:20),s.PlayerControl,s.Revision).Code);}
    [Fact]public void EmptyPrivateRiceDoesNotTakeFromHouse(){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.EatPrivateRice).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(1)][InlineData(3)]public void PurchasedFoodConsumesRealMerchantRiceAndCoins(long n){var s=Start();long price=s.RegionalTradeView()!.BuyPrice;var id=Food(s,n);Good(s.TradeRice(new(new("request:eat-cargo"),TradeAction.Consume,Kofu,id),s.PlayerControl,s.Revision));Assert.Equal(1000-price*n,s.PersonalLifeView()!.PrivateMoney);Assert.Equal(2000-n,s.DiagnosticSnapshot().Trade!.Markets.Single(m=>m.Site==Kofu).Rice);Assert.Equal(n,s.PersonalLifeView()!.MealRiceConsumed);Assert.Equal(TradePhase.Consumed,s.DiagnosticSnapshot().Trade!.Deals.Single().Phase);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:sell-eaten"),TradeAction.OfferSale,Kofu,id),s.PlayerControl,s.Revision).Code);}
    [Fact]public void LargeCargoCannotBeDestroyedAsAMeal(){var s=Start();var id=Food(s,4);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:four-kg-meal"),TradeAction.Consume,Kofu,id),s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(false)][InlineData(true)]public void GoalCountsOnlyRealPostSelectionSalaryReceipt(bool employee){var s=Start(employee);Good(Act(s,LifeAction.SetGoal,goal:employee?LifeGoal.ReceiveStipend:LifeGoal.PayStipend,target:20));Salary(s);var g=s.PersonalLifeView()!.Goals.Single();Assert.True(g.Achieved);Assert.Equal(20,g.Progress);if(employee){Good(Act(s,LifeAction.EatPrivateRice));Assert.True(s.PersonalLifeView()!.Goals.Single().Achieved);}Assert.False(s.Paused==false&&s.Seconds==0);}
    [Fact]public void GoalDoesNotCountOlderReceiptsAndCanBeChanged(){var s=Start(true);Salary(s);Good(Act(s,LifeAction.SetGoal,goal:LifeGoal.ReceiveStipend,target:20));Assert.Equal(0,s.PersonalLifeView()!.Goals.Single().Progress);Good(Act(s,LifeAction.SetGoal,goal:LifeGoal.WorkPay,target:40));Assert.Equal(2,s.PersonalLifeView()!.Goals.Length);Assert.All(s.PersonalLifeView()!.Goals,g=>Assert.False(g.Achieved));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedFeeSiteOrGoalIsRejected(int kind){var s=Start();Good(Act(s,LifeAction.RestInn));var w=s.DiagnosticSnapshot();var e=w.Life!.Entries.Single();e=kind==0?e with{Paid=0}:kind==1?e with{Input=e.Input with{Site=new("site:castle")}}:e with{Input=e.Input with{Target=99}};w.Life=w.Life with{Entries=[e]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldVersionKeepsNoLifeLedgerAndRejectsConsumption(){var s=Start(policy:RoadConvoy.Policy);var old=ContractJson.Write(s.DiagnosticSnapshot());Assert.Null(s.PersonalLifeView());Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.RestInn).Code);Assert.Equal(old,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(old)).DiagnosticSnapshot()));}
    [Fact]public void RestChunkSizeKeepsSameElapsedRestAndBalance(){var a=Start();var b=Start();Good(Act(a,LifeAction.RestInn));Good(Act(b,LifeAction.RestInn));Advance(a,7200);foreach(var t in new long[]{1,61,2000,7199,7200})Advance(b,t);Assert.Equal(ContractJson.Write(a.PersonalLifeView()),ContractJson.Write(b.PersonalLifeView()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void ActualGenerationRestMealGoalRecoveryAndFuture(int phase){var a=Start(phase>=5);if(phase==0)Good(Act(a,LifeAction.SetGoal,target:20));if(phase is 1 or 2 or 3){Good(Act(a,LifeAction.RestInn));Advance(a,120);if(phase==2)Good(Act(a,LifeAction.CancelRest,a.PersonalLifeView()!.ActiveRest));if(phase==3)Advance(a,7200);}if(phase==4){var id=Food(a);Good(a.TradeRice(new(new("request:save-meal"),TradeAction.Consume,Kofu,id),a.PlayerControl,a.Revision));}if(phase>=5){Good(Act(a,LifeAction.SetGoal,goal:LifeGoal.ReceiveStipend,target:20));Salary(a);if(phase>=6)Good(Act(a,LifeAction.EatPrivateRice));if(phase==7)Good(Act(a,LifeAction.RestOutside));}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"life-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"life",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("life"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.PersonalLifeView()),ContractJson.Write(b.PersonalLifeView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"personal-life-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"personal-life-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b})Advance(q,q.Seconds+15000);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.PersonalLifeView()),ContractJson.Write(b.PersonalLifeView()));}
    [Fact]public void WorkGoalRequiresActualPersonalReceiptAndSurvivesLaterSpending(){var s=Start();Good(Act(s,LifeAction.SetGoal,target:20));Good(s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:life-work"),s.Revision));Advance(s,1);var t=s.DiagnosticSnapshot().Tasks.Last();var order=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id.Value.EndsWith("/order"));Good(s.Open(s.PlayerControl,order.Id,s.Revision));if(t.Kind==TaskKind.VoluntaryRequest)Good(s.Assent(t.Id,s.PlayerControl,true,s.Revision));Advance(s,7);var notice=AssessmentNotice.Inbox(s,s.PlayerControl).Last();Good(s.Open(s.PlayerControl,notice.Message,s.Revision));Assert.False(s.PersonalLifeView()!.Goals.Single().Achieved);Good(s.CollectWorkPayment(new("payment:life-work"),t.Id,s.PlayerControl,s.Revision));Assert.True(s.PersonalLifeView()!.Goals.Single().Achieved);Good(Act(s,LifeAction.RestInn));Assert.True(s.PersonalLifeView()!.Goals.Single().Achieved);}
    [Fact]public void ZeroMoneyStillAllowsFreeRestWalkingAndWorkSearch(){var s=Start();while(s.PersonalLifeView()!.PrivateMoney>=s.RegionalTradeView()!.BuyPrice){long n=Math.Min(100,s.PersonalLifeView()!.PrivateMoney/s.RegionalTradeView()!.BuyPrice);var id=Food(s,n);Good(s.TradeRice(new(new("request:life-house/"+s.Revision),TradeAction.SupplyHouse,Kofu,id),s.PlayerControl,s.Revision));}Assert.Equal(0,s.PersonalLifeView()!.PrivateMoney);Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.RestInn).Code);Good(Act(s,LifeAction.RestOutside));Good(Act(s,LifeAction.CancelRest,s.PersonalLifeView()!.ActiveRest));var walker=new WorldSession(s.DiagnosticSnapshot());Good(walker.Submit(TravelWorld.Move(walker.DiagnosticSnapshot(),"request:poor-walk","castle") with{RoutePolicy=VoyageExpense.WalkOnly},walker.Revision));Advance(walker,2);Assert.Equal(0,walker.PersonalLifeView()!.PrivateMoney);Assert.NotEmpty(walker.DiagnosticSnapshot().Branches!.Journeys);Good(s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:poor-work"),s.Revision));}
    [Fact]public void AReservedPurchaseCannotBeUsedAsInnMoney(){var s=Start();for(int k=0;k<2;k++){var id=Food(s,100);Good(s.TradeRice(new(new("request:reserve-house/"+s.Revision),TradeAction.SupplyHouse,Kofu,id),s.PlayerControl,s.Revision));}var quote=new EntityId("request:reserve-food");Good(s.TradeRice(new(quote,TradeAction.Quote,Kofu,Destination:Kofu,Amount:50),s.PlayerControl,s.Revision));Good(s.TradeRice(new(new("request:reserve-confirm"),TradeAction.Accept,Kofu,quote),s.PlayerControl,s.Revision));Assert.Equal(0,s.PersonalLifeView()!.PrivateMoney);Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.RestInn).Code);Good(Act(s,LifeAction.RestOutside));}
    [Fact]public void FoodAndTradeDuringRestAreAtomicRejections(){var s=Start(true);Salary(s);Good(Act(s,LifeAction.RestOutside));var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.EatPrivateRice).Code);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:sleep-food"),TradeAction.Quote,Kofu,Destination:Kofu,Amount:1),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void SalaryArrearsRemainSeparateAfterEndingService(){var s=Start(true);Salary(s);Advance(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[1]);Assert.Equal(20,s.PersonalLifeView()!.StipendReceivable);Assert.Equal(0,s.PersonalLifeView()!.StipendPayable);var service=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single().Case;Good(s.DecideService(new(new("request:life-release"),CareerAction.RequestRelease,service),s.PlayerControl,s.Revision));Advance(s,s.Seconds+3);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));Assert.Equal("浪人",s.PersonalLifeView()!.Role);Assert.Equal(20,s.PersonalLifeView()!.StipendReceivable);Assert.Equal(20,s.PersonalLifeView()!.PrivateRice);}
    [Fact]public void AfterEatingOnlyRemainingPrivateRiceCanBeLoadedForSale(){var s=Start(true);Salary(s);Good(Act(s,LifeAction.EatPrivateRice));Good(s.TradeRice(new(new("request:remaining-food"),TradeAction.OfferOwnRice,Kofu,Destination:Kofu,Amount:19),s.PlayerControl,s.Revision));Assert.Equal(0,s.PersonalLifeView()!.PrivateRice);Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.EatPrivateRice).Code);}
    [Fact]public void NormalProfileBuildEnablesLifeWithoutChangingLegacy(){var seed=Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"life-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(seed.Start,[],seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,null,PersonalLife.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.PersonalLifeView());Assert.True(RoadConvoy.Enabled(s.DiagnosticSnapshot()));Assert.NotNull(s.DiagnosticSnapshot().ArmyRoad);}

    [Fact]public void HeldArmyIsShownAsAnObligationAndPreventsPrivateRest(){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:PersonalLife.Policy));void Send(NewMilitaryAction action){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:life-army/"+s.Revision),action){AuthorityPolicy=action==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=action==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=action==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=action==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}void Open(){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}Send(NewMilitaryAction.Request);Advance(s,2);Open();Send(NewMilitaryAction.Accept);Advance(s,4);Open();Send(NewMilitaryAction.Pickup);var v=s.PersonalLifeView()!;Assert.True(v.HoldsArmy);Assert.False(v.CanRest);Assert.Contains("返報",v.Burden);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageLife(new(new("request:army-rest"),LifeAction.RestOutside,v.Site!.Value),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}

    [Theory][InlineData(StartTemplate.Subretainer)][InlineData(StartTemplate.Castellan)][InlineData(StartTemplate.LocalLord)]public void KnownCreatedRoleIsNotFlattenedIntoOrdinaryRetainer(StartTemplate role){RegisteredOfficer[] records=role==StartTemplate.Subretainer?[NewGameWorldTests.Officer("created:upper",StartTemplate.Retainer,lord:"person:nobunaga"),NewGameWorldTests.Officer(role:role,lord:"created:upper")]:[NewGameWorldTests.Officer(role:role,lord:"person:nobunaga")];var setup=NewGameWorldTests.Setup(records);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:test",inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:PersonalLife.Policy));var before=s.DiagnosticSnapshot();Assert.Equal(NewGameWorld.RoleName(role),s.PersonalLifeView()!.Role);var site=s.PersonalLifeView()!.Site!.Value;Good(s.ManageLife(new(new("request:role-free-rest"),LifeAction.RestOutside,site),s.PlayerControl,s.Revision));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(s.DiagnosticSnapshot().LandRights));Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(s.DiagnosticSnapshot().Offices));}
    [Fact]public void EntrustedFreightIsAContinuingObligationAndBlocksRest(){var s=Start();Good(s.ManageHouseFreight(new(new("request:life-freight"),HouseFreightAction.Dispatch,Home:Kofu,Source:new("site:castle"),Commodity:"wood",Quantity:1,Advance:10),s.PlayerControl,s.Revision));Assert.False(s.PersonalLifeView()!.CanRest);Assert.Contains("帰還精算",s.PersonalLifeView()!.Burden);Assert.Equal(ResultCode.NotAvailable,Act(s,LifeAction.RestOutside).Code);}

}
